function readRecent(dirPath, limit = 5) {
  try {
    const files = fs.readdirSync(dirPath)
      .filter((f) => f.endsWith('.md') || f.endsWith('.json') || f.endsWith('.txt'))
      .map((name) => ({
        name,
        fullPath: path.join(dirPath, name),
        mtimeMs: fs.statSync(path.join(dirPath, name)).mtimeMs,
      }))
      .sort((a, b) => b.mtimeMs - a.mtimeMs)
      .slice(0, limit);

    if (!files.length) return 'нет данных';

    return files.map((file) => {
      let body = 'нет данных';
      try {
        body = clip(fs.readFileSync(file.fullPath, 'utf8'), 700);
      } catch (e) {}
      return `## ${file.name}\n${body}`;
    }).join('\n\n---\n\n');
  } catch (e) {
    return 'нет данных';
  }
}

