function clip(value, limit = 4000) {
  const text = String(value || '');
  return text.length > limit ? text.slice(0, limit) + '\n...[truncated]' : text;
}

function relFromAbs(absPath) {
  return path.relative(ROOT, absPath).replace(/\\/g, '/');
}

function resolveVaultPath(inputPath) {
  const requested = String(inputPath || '').replace(/\\/g, '/').replace(/^\/obsidian\/?/, '').replace(/^\/+/, '');
  const abs = path.resolve(ROOT, requested || '.');
  const rootResolved = path.resolve(ROOT);
  if (!(abs === rootResolved || abs.startsWith(rootResolved + path.sep))) {
    throw new Error('Path escapes /obsidian');
  }
  return abs;
}

function ensureDirFor(absPath) {
  fs.mkdirSync(path.dirname(absPath), { recursive: true });
}

function backupIfExists(absPath) {
  if (!fs.existsSync(absPath) || !fs.statSync(absPath).isFile()) return null;
  const backupsDir = path.join(ROOT, 'System', 'backups');
  fs.mkdirSync(backupsDir, { recursive: true });
  const rel = relFromAbs(absPath).replace(/[\/]/g, '__');
  const stamp = new Date().toISOString().replace(/[:.]/g, '-');
  const backupPath = path.join(backupsDir, `${stamp}__${rel}`);
  fs.copyFileSync(absPath, backupPath);
  return '/obsidian/' + relFromAbs(backupPath);
}

function appendActionLog(entry) {
  const logPath = path.join(ROOT, 'System', 'action-log.jsonl');
  fs.mkdirSync(path.dirname(logPath), { recursive: true });
  const payload = {
    ts: new Date().toISOString(),
    ...entry,
  };
  fs.appendFileSync(logPath, JSON.stringify(payload, ensureAsciiSafe) + '\n', 'utf8');
}

function ensureAsciiSafe(key, value) {
  if (typeof value === 'string' && value.length > 8000) return value.slice(0, 8000) + '...[truncated]';
  return value;
}

function scanFiles(startAbs, depth = 4, out = [], currentDepth = 0) {
  if (out.length > 400) return out;
  let entries = [];
  try { entries = fs.readdirSync(startAbs, { withFileTypes: true }); } catch (e) { return out; }
  for (const entry of entries) {
    if (out.length > 400) break;
    const full = path.join(startAbs, entry.name);
    if (entry.isDirectory()) {
      if (currentDepth < depth && !['.git', 'node_modules'].includes(entry.name)) {
        scanFiles(full, depth, out, currentDepth + 1);
      }
    } else if (entry.isFile()) {
      out.push(full);
    }
  }
  return out;
}

function obsidianListDir(args = {}) {
  const abs = resolveVaultPath(args.path || '.');
  const recursive = !!args.recursive;
  const limit = Math.min(Math.max(Number(args.limit || 50), 1), 200);
  if (recursive) {
    const files = scanFiles(abs, Number(args.depth || 3)).slice(0, limit).map((full) => ({
      path: '/obsidian/' + relFromAbs(full),
      type: fs.statSync(full).isDirectory() ? 'directory' : 'file',
    }));
    return { path: '/obsidian/' + relFromAbs(abs), entries: files };
  }
  const entries = fs.readdirSync(abs, { withFileTypes: true })
    .slice(0, limit)
    .map((entry) => {
      const full = path.join(abs, entry.name);
      const stat = fs.statSync(full);
      return {
        name: entry.name,
        path: '/obsidian/' + relFromAbs(full),
        type: entry.isDirectory() ? 'directory' : 'file',
        size: stat.size,
        mtime: stat.mtime.toISOString(),
      };
    });
  return { path: '/obsidian/' + relFromAbs(abs), entries };
}

function obsidianReadFile(args = {}) {
  const abs = resolveVaultPath(args.path || '');
  const stat = fs.statSync(abs);
  if (!stat.isFile()) throw new Error('Not a file');
  const maxChars = Math.min(Math.max(Number(args.max_chars || 6000), 200), 30000);
  const text = fs.readFileSync(abs, 'utf8');
  return {
    path: '/obsidian/' + relFromAbs(abs),
    size: stat.size,
    content: clip(text, maxChars),
  };
}

function obsidianSearch(args = {}) {
  const query = String(args.query || '').trim().toLowerCase();
  const limit = Math.min(Math.max(Number(args.limit || 8), 1), 20);
  const start = resolveVaultPath(args.path || '.');
  const files = scanFiles(start, Number(args.depth || 4));
  const matches = [];
  for (const full of files) {
    if (matches.length >= limit) break;
    let stat;
    try { stat = fs.statSync(full); } catch (e) { continue; }
    if (!stat.isFile()) continue;
    if (stat.size > 500000) continue;
    const rel = '/obsidian/' + relFromAbs(full);
    const name = path.basename(full).toLowerCase();
    let hay = name;
    let body = '';
    try {
      if (/\.(md|txt|json)$/i.test(full)) {
        body = fs.readFileSync(full, 'utf8');
        hay += '\n' + body.toLowerCase();
      }
    } catch (e) {}
    if (!query || hay.includes(query)) {
      const idx = query ? hay.indexOf(query) : 0;
      const previewSource = body || name;
      const preview = query && idx >= 0
        ? clip(previewSource.slice(Math.max(0, idx - 180), idx + 380), 700)
        : clip(previewSource, 700);
      matches.push({ path: rel, name: path.basename(full), preview, mtime: stat.mtime.toISOString() });
    }
  }
  return { query, matches };
}

function obsidianWriteFile(args = {}) {
  const abs = resolveVaultPath(args.path || '');
  const content = String(args.content || '');
  ensureDirFor(abs);
  const backup = backupIfExists(abs);
  fs.writeFileSync(abs, content, 'utf8');
  return { ok: true, path: '/obsidian/' + relFromAbs(abs), bytes: Buffer.byteLength(content, 'utf8'), backup };
}

function obsidianAppendFile(args = {}) {
  const abs = resolveVaultPath(args.path || '');
  const content = String(args.content || '');
  ensureDirFor(abs);
  if (!fs.existsSync(abs)) {
    fs.writeFileSync(abs, content, 'utf8');
    return { ok: true, path: '/obsidian/' + relFromAbs(abs), mode: 'create', bytes: Buffer.byteLength(content, 'utf8') };
  }
  backupIfExists(abs);
  fs.appendFileSync(abs, content, 'utf8');
  return { ok: true, path: '/obsidian/' + relFromAbs(abs), mode: 'append', bytes: Buffer.byteLength(content, 'utf8') };
}

