function reminderUpsert(args = {}) {
  const registryPath = path.join(ROOT, 'System', 'reminders.json');
  fs.mkdirSync(path.dirname(registryPath), { recursive: true });
  const registry = readJsonFile(registryPath, { version: 1, updated_at: null, items: [] });
