    ask_for_status: !!args.ask_for_status,
    updated_at: now,
    created_at: now,
    meta: args.meta || {},
  };
  const idx = registry.items.findIndex((x) => x.id === item.id);
  if (idx >= 0) {
    item.created_at = registry.items[idx].created_at || now;
